// Normaliza la salida del Agente Otro (JSON {responder, respuesta, motivo}).
// final = el texto a enviar (vacio => rama de silencio); hayRespuesta rutea el IF.
// accion='otro' para la telemetria de salidas (ver backlog B-29).
// Ante cualquier falla de parseo, responder=false => silencio (default seguro).
const d = $('Prompt Otro').first().json;
let out = {};
try {
  const raw = $input.first().json;
  out = raw.output || raw.data || raw;
  if (typeof out === 'string') out = JSON.parse(out);
} catch (e) { out = {}; }
// parse robusto: json_object puede devolver el bool como string 'true'
const responder = out.responder === true || out.responder === 'true';
const respuesta = String(out.respuesta || '').trim();
// GUARD DETERMINISTICO (Fable 2026-08-06): sin datos del negocio no hay adonde
// derivar. No se confia en que el LLM respete la regla del prompt: se fuerza el
// silencio aca. Un mensaje de derivacion sin mail/local no le sirve al cliente.
const sinDatos = (d.infoFilas || 0) === 0;
const final = (responder && respuesta && !sinDatos) ? respuesta : '';
return [{ json: {
  ...d,
  final,
  accion: 'otro',
  hayRespuesta: final.length > 0,
  motivoOtro: String(out.motivo || ''),
  notas: 'v10-otro-fallback ' + (final ? 'fuente=responde' : 'fuente=silencio'),
} }];
